def monitor(
    runner: Runner,
    *,
    pr: int,
    repo: str,
    base_remote: str = "origin",
    base_ref: str = "main",
    empty_checks_grace: int = 0,
    iteration: int = 0,
    rebase_count: int = 0,
    fix_attempts: int = 0,
    transient_retries: int = 0,
    plan_file: str | None = None,
    ci_fix_rebase_pending: bool = False,
    ctx: RunContext | None = None,
    cwd: str | None = None,
    launch_fn: LaunchFn | None = None,
    sleep_fn: SleepFn = time.sleep,
    clock: ClockFn = time.monotonic,
) -> MonitorResult:
    """Driver entrypoint for CI monitor loop."""
    status, decision = poll_ci(
        runner,
        pr=pr,
        repo=repo,
        base_remote=base_remote,
        base_ref=base_ref,
        empty_checks_grace=empty_checks_grace,
        iteration=iteration,
        rebase_count=rebase_count,
        fix_attempts=fix_attempts,
        sleep_fn=sleep_fn,
        clock=clock,
        cwd=cwd,
    )

    def _base_result(
        *,
        did_fixing: bool,
        goto: bool,
        step: StepResult,
        rerun_already_running: bool = False,
        transient_rerun_attempted: bool = False,
        pending: bool = ci_fix_rebase_pending,
    ) -> MonitorResult:
        return MonitorResult(
            action=decision.action,
            ci_status=status.status,
            behind_count=status.behind_count,
            failed_run_id=status.failed_run_id,
            did_fixing=did_fixing,
            goto_rebase=goto,
            iterations=iteration,
            result=step,
            rerun_already_running=rerun_already_running,
            transient_rerun_attempted=transient_rerun_attempted,
            ci_fix_rebase_pending=pending,
        )

    if decision.action in ("merge", "already_merged"):
        return _base_result(
            did_fixing=False,
            goto=False,
            step=StepResult(outcome=Outcome.OK),
        )

    if decision.action == "rebase":
        return _base_result(
            did_fixing=False,
            goto=True,
            step=StepResult(outcome=Outcome.OK),
        )

    if decision.action in ("evaluate_failure", "rebase_then_evaluate"):
        if decision.action == "rebase_then_evaluate":
            return _base_result(
                did_fixing=False,
                goto=True,
                step=StepResult(outcome=Outcome.OK),
            )
        if not status.failed_run_id:
            return _base_result(
                did_fixing=False,
                goto=False,
                step=StepResult(
                    outcome=Outcome.STALLED,
                    detail="missing failed_run_id",
                ),
            )
        fix = evaluate_failure(
            runner,
            pr=pr,
            run_id=status.failed_run_id,
            repo=repo,
            plan_file=plan_file,
            transient_retries=transient_retries,
            _fix_attempts=fix_attempts,
            cwd=cwd,
            launch_fn=launch_fn,
            sleep_fn=sleep_fn,
            clock=clock,
            base_remote=base_remote,
            base_ref=base_ref,
            ci_fix_rebase_pending=ci_fix_rebase_pending,
            ctx=ctx,
        )
        if fix.status == "ci-still-in-progress":
            return _base_result(
                did_fixing=False,
                goto=False,
                step=StepResult(outcome=Outcome.OK),
            )
            status,
            decision,
            iteration=args.iteration,
            elapsed=elapsed,
        )
        text = "\n".join(lines) + "\n"
        if _publish_wait_output(text, output_file):
            done_path = out_path.with_name(out_path.name + ".done")
            with contextlib.suppress(OSError):
                _ = done_path.write_text(f"{trap_exit}\n", encoding="utf-8")

    if output_file:

        def _signal_handler(signum: int, _frame: object) -> None:
            nonlocal trap_exit
            trap_exit = 128 + signum
            _publish_trap_output()
            raise SystemExit(trap_exit)

        for sig in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
            with contextlib.suppress(ValueError, OSError):
                old_signal_handlers[sig] = cast(
                    "signal.Handlers",
                    signal.signal(sig, _signal_handler),
                )

    try:
        started = time.monotonic()
        status, decision = ci_monitor.poll_ci(
            proc,
            pr=args.pr,
            repo=args.repo,
            base_remote=args.base_remote,
            base_ref=args.base_ref,
