        )
        elapsed = int(time.monotonic() - started)
        trap_exit = 0
    except Exception:
        trap_exit = 1
        if not output_file:
            raise
    finally:
        if output_file:
            for sig, handler in old_signal_handlers.items():
                with contextlib.suppress(ValueError, OSError):
                    signal.signal(sig, handler)
            _publish_trap_output()

